mapper.select:
SELECT approval_complete_rate FROM stat_approval_rpt WHERE deleted = 0
AND stat_cycle = #{statCycle}
ORDER BY stat_time DESC LIMIT 1

SELECT pol_fulfill_rate FROM stat_pol_rpt WHERE deleted = 0
AND stat_cycle = #{statCycle}
ORDER BY stat_time DESC LIMIT 1

SELECT ent_satisfy FROM stat_satisfy_rpt WHERE deleted = 0
AND stat_cycle = #{statCycle}
ORDER BY stat_time DESC LIMIT 1

SELECT appeal_overdue_rate FROM stat_appeal_rpt WHERE deleted = 0
AND stat_cycle = #{statCycle}
ORDER BY stat_time DESC LIMIT 1

SELECT sa.region_name as regionName, sar.complete_rate as completeRate FROM stat_approval_rpt sar LEFT JOIN sys_area sa ON sar.region_code = sa.region_code WHERE sar.deleted = 0 AND sar.stat_time = ( SELECT MAX(stat_time) FROM stat_approval_rpt sar2 WHERE sar2.region_code = sar.region_code AND sar2.deleted = 0
AND sar2.stat_cycle = #{statCycle}
)
AND sar.stat_cycle = #{statCycle}
AND sar.region_code IS NOT NULL ORDER BY sar.complete_rate DESC
